    "name_hi": "दाल ढोकली",
    "name_gu": "દાળ ઢોકળી",
    "description_hi": "खट्टी-मीठी तुअर दाल में पकाई गई गेहूं के आटे की मसालेदार ढोकली, घी और मूंगफली के साथ संपूर्ण भोजन।",
    "description_gu": "તુવેરની ખાટી-મીઠી દાળમાં ચડવેલી મસાલેદાર ઘઉંના લોટની ઢોકળી, શુદ્ધ ઘી અને સીંગદાણા સાથે સંપૂર્ણ ભોજન.",
    "total_time": 50,
    "prep_instructions_en": "Boil toor dal until soft. Knead spiced whole wheat dough and roll thin diamond shapes.",
    "prep_instructions_hi": "तुअर दाल को उबालें। मसालेदार गेहूं का आटा गूंथकर पतली डायमंड आकार की ढोकली काटें।",
    "prep_instructions_gu": "તુવેરની દાળ બાફી લો. ઘઉંનો મસાલાવાળો લોટ બાંધી પાતળી રોટલી વણી કાપા પાડી લો.",
    "common_mistakes_en": "Adding dhokli to cold dal causes them to stick together; dal must be at a rolling boil.",
    "common_mistakes_hi": "उबलती हुई दाल में ही एक-एक करके ढोकली डालें, ठंडी दाल में डालने से चिपक जाएंगी।",
    "common_mistakes_gu": "દાળ ખદખદતી ઉકળતી હોય ત્યારે જ એક-એક કરીને ઢોકળી ઉમેરવી, જેથી ચોંટે નહીં.",
    "storage_en": "Best eaten freshly made as dhokli absorbs all liquid upon standing. Add hot water if reheating.",
    "storage_hi": "ताजा ही खाएं क्योंकि ढोकली सारा रस सोख लेती है। दोबारा गर्म करते समय गर्म पानी मिलाएं।",
    "storage_gu": "તાજી જ ખાવી સારી, કારણ કે ઢોકળી બધો રસો પી જાય છે. ગરમ કરતી વખતે ગરમ પાણી ઉમેરવું.",
    "tips_en": "Adding dhokli to cold dal causes them to stick together; dal must be at a rolling boil.",
    "tips_hi": "उबलती हुई दाल में ही एक-एक करके ढोकली डालें, ठंडी दाल में डालने से चिपक जाएंगी।",
