    "description_hi": "लाल रसीली गाजर, दूध, खोया, शुद्ध देसी घी और मेवों से धीमी आंच पर पकाया गया पारंपरिक शाही हलवा।",
    "description_gu": "લાલ રસદાર ગાજર, દૂધ, માવો, શુદ્ધ દેશી ઘી અને કાજુ-બદામમાંથી ધીમી આંચે બનતો શિયાળાનો શાહી હલવો.",
    "total_time": 65,
    "prep_instructions_en": "Grate fresh red winter carrots. Simmer with full-fat milk until liquid evaporates.",
    "prep_instructions_hi": "लाल गाजर कद्दूकस करें। मलाईदार दूध के साथ दूध सूखने तक पकाएं।",
    "prep_instructions_gu": "લાલ ગાજર ખમણી લો. ફુલ ક્રીમ દૂધ સાથે દૂધ બળી જાય ત્યાં સુધી ઉકાળો.",
    "common_mistakes_en": "Adding sugar before carrots are cooked makes carrots stiff.",
    "common_mistakes_hi": "गाजर गलने से पहले चीनी डालने से गाजर कड़क रह जाती है।",
    "common_mistakes_gu": "ગાજર ચડે તે પહેલાં ખાંડ નાખવાથી ગાજર કડક રહી જાય છે.",
    "storage_en": "Refrigerate for up to 10 days. Reheat with a spoonful of ghee.",
    "storage_hi": "10 दिन फ्रिज में रख सकते हैं। थोड़ा घी डालकर गर्म करें।",
