    "tips_en": "Adding sugar before carrots are cooked makes carrots stiff.",
    "tips_hi": "गाजर गलने से पहले चीनी डालने से गाजर कड़क रह जाती है।",
    "tips_gu": "ગાજર ચડે તે પહેલાં ખાંડ નાખવાથી ગાજર કડક રહી જાય છે.",
