    "description_hi": "कंडे या ओवन में सिकी गेहूं की खस्ता बाटी, पंचमेल दाल, शुद्ध देसी घी और मीठे इलायची वाले चूरमे का राजपूती भोज।",
    "description_gu": "ઓવન કે કંડાર પર શેકેલી ખસ્તા બાટી, પંચમેલ દાળ, શુદ્ધ દેશી ઘી અને એલચીવાળા ગળ્યા ચૂરમાનો રાજપૂતી થાળ.",
    "total_time": 75,
