    "common_mistakes_gu": "ઢીલો લોટ બાંધવાથી બાટી અંદરથી કાચી રહી જાય છે.",
    "storage_en": "Baatis and churma keep for days at room temp. Dal keeps 2 days in fridge.",
    "storage_hi": "बाटी और चूरमा कई दिन कमरे में रहते हैं। दाल 2 दिन फ्रिज में रखें।",
    "storage_gu": "બાટી અને ચૂરમો ઘણા દિવસ સારાં રહે છે. દાળ ૨ દિવસ ફ્રિજમાં રાખવી.",
